package org.eclipse.rdf4j.workbench.commands;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF4J;
import org.eclipse.rdf4j.model.vocabulary.RDFS;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.eclipse.rdf4j.workbench.commands.ExploreQuery.Section;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;

class ExploreServletTest {

	private SailRepository repository;
	private RepositoryConnection connection;
	private ValueFactory factory;
	private IRI resource;
	private IRI other;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
		connection = repository.getConnection();
		factory = repository.getValueFactory();
		resource = factory.createIRI("urn:test:resource");
		other = factory.createIRI("urn:test:other");
	}

	@AfterEach
	void tearDown() {
		connection.close();
		repository.shutDown();
	}

	@ParameterizedTest
	@EnumSource(value = Section.class, names = { "OUTGOING", "INCOMING", "PREDICATE", "GRAPH" })
	void selfLinksAppearInEachApplicableRoleAndCountDistinctContexts(Section section) {
		connection.add(resource, resource, resource);
		connection.add(resource, resource, resource, resource);

		List<BindingSet> rows = rows(section, false, null, resource, null);
		assertThat(rows).hasSize(section == Section.GRAPH ? 1 : 2);
		assertThat(rows).allSatisfy(row -> {
			assertThat(row.getValue("subject")).isEqualTo(resource);
			assertThat(row.getValue("predicate")).isEqualTo(resource);
			assertThat(row.getValue("object")).isEqualTo(resource);
		});
		if (section == Section.GRAPH) {
			assertThat(count(section, null, resource)).isEqualTo("1");
		} else {
			assertThat(count(section, "default", resource)).isEqualTo("1");
			assertThat(count(section, "named", resource)).isEqualTo("1");
		}
	}

	@Test
	void namedNilGraphIsNotConfusedWithPhysicalDefaultGraph() {
		connection.add(other, resource, other);
		connection.add(other, resource, other, RDF4J.NIL);
		List<BindingSet> graph = rows(Section.GRAPH, false, null, RDF4J.NIL, null);
		assertThat(graph).hasSize(1);
		assertThat(graph.getFirst().getValue("context")).isEqualTo(RDF4J.NIL);
		assertThat(count(Section.GRAPH, null, RDF4J.NIL)).isEqualTo("1");
		assertThat(count(Section.PREDICATE, "default", resource)).isEqualTo("1");
		assertThat(count(Section.PREDICATE, "named", resource)).isEqualTo("1");
	}

	@ParameterizedTest
	@EnumSource(value = Section.class, names = { "TYPES", "SUPER_CLASSES", "SUB_CLASSES", "PROPERTIES",
			"SUPER_PROPERTIES", "SUB_PROPERTIES", "DOMAIN", "RANGE" })
	void summaryValuesAreDistinctAcrossGraphsAndExcludeTheExploredValue(Section section) {
		IRI predicate = factory.createIRI(section.predicate);
		if (section.inverse) {
			connection.add(other, predicate, resource);
			connection.add(other, predicate, resource, other);
		} else {
			connection.add(resource, predicate, other);
			connection.add(resource, predicate, other, other);
		}
		connection.add(resource, predicate, resource);
		assertThat(rows(section, false, null, resource, null))
				.extracting(row -> row.getValue("value"))
				.containsExactly(other);
		assertThat(count(section, null, resource)).isEqualTo("1");
	}

	@Test
	void escapedLiteralOperandsAreUsedAsValuesRatherThanQueryText() {
		Value literal = factory.createLiteral("quote " + (char) 34 + " slash " + (char) 92 + (char) 10, "en");
		connection.add(other, resource, literal);
		assertThat(rows(Section.INCOMING, false, null, literal, null))
				.extracting(row -> row.getValue("object"))
				.containsExactly(literal);
		assertThat(count(Section.INCOMING, "default", literal)).isEqualTo("1");
	}

	@Test
	void preferredLanguageCanAppearAfterManyOtherLabels() {
		for (int i = 0; i < 70; i++) {
			connection.add(resource, RDFS.LABEL, factory.createLiteral("other-" + i, "de"));
		}
		Value preferred = factory.createLiteral("preferred", "nb-NO");
		connection.add(resource, RDFS.LABEL, preferred);
		connection.add(resource, RDFS.LABEL, factory.createLiteral("english", "en"));
		assertThat(rows(Section.LABEL, false, null, resource, new String[] { "nb-NO", "en" }))
				.extracting(row -> row.getValue("value"))
				.containsExactly(preferred);
	}

	private String count(Section section, String scope, Value target) {
		return rows(section, true, scope, target, null).getFirst().getValue("total").stringValue();
	}

	private List<BindingSet> rows(Section section, boolean count, String scope, Value target, String[] languages) {
		ExploreQuery spec = ExploreQuery.create(section, count, scope, section.scalar() ? 1 : 100,
				true, target, languages, factory);
		List<BindingSet> rows = new ArrayList<>();
		try (TupleQueryResult result = spec.prepare(connection, 10).evaluate()) {
			while (result.hasNext()) {
				rows.add(result.next());
			}
		}
		return rows;
	}
}
